package pl.atrop.powerguard.bcknd.site.infrastructure.rest;
import jakarta.inject.Inject; import jakarta.ws.rs.*; import jakarta.ws.rs.core.*; import java.util.*; import pl.atrop.powerguard.bcknd.auth.application.SiteAccessGuard; import pl.atrop.powerguard.bcknd.auth.domain.UserAccount; import pl.atrop.powerguard.bcknd.auth.infrastructure.rest.AuthErrorResponse; import pl.atrop.powerguard.bcknd.site.domain.*;
@Path("sites") @Consumes(MediaType.APPLICATION_JSON) @Produces(MediaType.APPLICATION_JSON) public class SitesResource{
 @Inject SitesService service; @Inject SiteAccessGuard access;
 @GET public Response publicSites(@HeaderParam("Authorization")String authorization){Optional<UserAccount> actor=access.currentUser(authorization);if(actor.isEmpty())return denied("Authentication required.",Response.Status.UNAUTHORIZED);return Response.ok(service.findPublicSites().stream().filter(s->access.canAccess(actor.get(),s.id())).map(SiteView::from).toList()).build();}
 @GET @Path("assignable") public Response assignable(@HeaderParam("Authorization")String authorization){Optional<UserAccount> actor=access.currentUser(authorization);if(actor.isEmpty())return denied("Authentication required.",Response.Status.UNAUTHORIZED);if(!access.isManager(actor.get()))return denied("Administrator or installer role required.",Response.Status.FORBIDDEN);return Response.ok(service.findAll().stream().filter(s->access.isAdminOrService(actor.get())||access.canAccess(actor.get(),s.id())).map(SiteView::from).toList()).build();}
 @GET @Path("admin") public Response all(@HeaderParam("Authorization")String authorization){Optional<UserAccount> actor=access.currentUser(authorization);if(actor.isEmpty()||!access.isAdminOrService(actor.get()))return denied("Administrator role required.",Response.Status.FORBIDDEN);return Response.ok(service.findAll().stream().map(SiteView::from).toList()).build();}
 @POST public Response create(@HeaderParam("Authorization")String authorization,SiteRequest r){Optional<UserAccount> actor=access.currentUser(authorization);if(actor.isEmpty()||!access.isAdmin(actor.get()))return denied("Administrator role required.",Response.Status.FORBIDDEN);if(r==null)return bad("Invalid site data.");return service.create(new SiteConfigurationInput(r.clientId(),r.siteId(),r.name(),r.enabled())).<Response>map(s->Response.status(201).entity(SiteView.from(s)).build()).orElseGet(()->bad("Invalid client/site data or duplicate Site ID inside the selected client."));}
 @PUT @Path("{clientId}/{siteId}") public Response update(@HeaderParam("Authorization")String authorization,@PathParam("clientId")String clientId,@PathParam("siteId")String siteId,SiteRequest r){Optional<UserAccount> actor=access.currentUser(authorization);if(actor.isEmpty()||!access.isAdmin(actor.get()))return denied("Administrator role required.",Response.Status.FORBIDDEN);if(r==null)return bad("Invalid site data.");return service.update(clientId,siteId,new SiteConfigurationInput(clientId,siteId,r.name(),r.enabled())).<Response>map(s->Response.ok(SiteView.from(s)).build()).orElseGet(()->bad("Invalid site data."));}
 @DELETE @Path("{clientId}/{siteId}") public Response delete(@HeaderParam("Authorization")String authorization,@PathParam("clientId")String clientId,@PathParam("siteId")String siteId){Optional<UserAccount> actor=access.currentUser(authorization);if(actor.isEmpty()||!access.isAdmin(actor.get()))return denied("Administrator role required.",Response.Status.FORBIDDEN);if(!service.delete(clientId,siteId))return Response.status(409).entity(new AuthErrorResponse("Site cannot be deleted while meters use it.")).build();return Response.noContent().build();}
 private Response denied(String m,Response.Status s){return Response.status(s).entity(new AuthErrorResponse(m)).build();} private Response bad(String m){return Response.status(400).entity(new AuthErrorResponse(m)).build();}
}
